// === Tab: mySketch ===
var frog
var stretch

var prev, apex, next
var fromTime = 1000, toTime = 1500

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)

	frog = buildGeometry(() => {
		fill('#44B444')
		push()
		translate(0, 5)
		sphere(15)
		translate(0, -10, 10)
		sphere(10)
		for (const side of [-1, 1]) {
			push()
			translate(side * 5, -5)
			fill('yellow')
			sphere(6)
			pop()
		}
		for (const side of [-1, 1]) {
			push()
			translate(side * 12, 15, -8)
			scale(0.4, 1, 0.4)
			sphere(10)
			pop()

			push()
			translate(side * 4, 18, 8)
			scale(0.4, 1, 0.4)
			sphere(8)
			pop()
		}
		pop()
	})
	prev = createVector(0, 0, 0)
	next = createVector(random(-1,1)*width/2, 0, -random(width))
	apex = prev.copy().add(next).div(2).add(0, -prev.dist(next)*1.5, 0)

	stretch = baseMaterialShader().modify(() => {
		const A = uniformVec3()
		const B = uniformVec3()
		const C = uniformVec3()
		const t1 = uniformFloat()
		const t2 = uniformFloat()

		const getPt = (t) => A * (1-t) * (1-t) +
			B * 2 * (1-t) * t +
			C * t * t

		getWorldInputs((inputs) => {
			const map = (val, f1, f2, t1, t2) => (val - f1)/(f2 - f1) * (t2 - t1) + t1
			const progress = 1 - map(inputs.position.y, -20, 20, 0, 1)
			const off = inputs.position - [0, inputs.position.y, 0]
			const t = mix(t1, t2, progress)
			const newPos = getPt(t) + off + progress * [0, -40, 0]

			inputs.position = newPos
			debugger
			return inputs
		})
	})
}

function draw() {
	var t = millis()
	var off = 50
	const progress1 = map(t, fromTime, toTime - off, 0, 1, true)
	const progress2 = map(t, fromTime + off, toTime, 0, 1, true)

	background(255)
	orbitControl()

	lights()
	noStroke()

	push()
	stretch.setUniform('A', [prev.x, prev.y, prev.z])
	stretch.setUniform('B', [apex.x, apex.y, apex.z])
	stretch.setUniform('C', [next.x, next.y, next.z])
	stretch.setUniform('t1', progress1)
	stretch.setUniform('t2', progress2)
	shader(stretch)
	model(frog)
	pop()

	if (progress2 === 1) {
		prev = next
		next = createVector(random(-1,1)*width/2, 0, -random(width))
		apex = prev.copy().add(next).div(2).add(0, -prev.dist(next)*1.5, 0)
		fromTime = t + 1000
		toTime = fromTime + prev.dist(next) * 0.6
	}
}
